import logging
import textwrap
from typing import NoReturn, Union

from taf.transport.ssh.connection import SSHConnection
from taf.transport.ssh.process import SSHProcess

from .exception import SyslogCLINotFoundError


class EnvironmentResolver:
    """
    This class is responsible for finding cli_syslog and providing the command to activate the
    environment in which it can be executed.

    We want to check environments in this order:
    1. virtualenv - if provided (if provided env does not have cli_syslog immediately raise an error)
    2. no environment
    3. pyenv
    """

    VIRUTALENV_CMD = "source {}/bin/activate; "
    PYENV_CMD = 'source $PYENV_ROOT/versions/{}/bin/activate; '
    NO_ENV_CMD = ""

    def __init__(self, ssh_connection: SSHConnection, virtualenv_dir: Union[str, None]):
        self._virtualenv_dir = virtualenv_dir
        self._ssh_connection = ssh_connection
        self._logger = logging.getLogger(__name__)

    def _send_ssh_command(self, cmd: str) -> SSHProcess:
        self._logger.debug(f"Sending command:\n {cmd}")
        process = self._ssh_connection.send_command(cmd)
        return process

    def resolve(self) -> str:
        """Resolve which environment should be used to execute cli_syslog.
        If no cli_syslog is found, raise an exception

        :return env_command: command to activate the needed environment
        :rtype: str
        :raises SyslogCLINotFoundError: when cli_syslog was not found in any environment or in the
            specified virtualenv.
        """
        if self._virtualenv_dir:
            self._logger.info(
                f"Virtualenv_dir provided: {self._virtualenv_dir}, "
                f"we will look for `cli_syslog` in this environment only."
            )
            virtualenv_cmd = self.VIRUTALENV_CMD.format(self._virtualenv_dir)
            if not self._syslog_available_in_environment(virtualenv_cmd):
                self._raise_cli_not_found_error(virtualenv_cmd)
            self._logger.info("`cli_syslog` found in provided virtualenv")
            return virtualenv_cmd

        if self._syslog_available_in_environment(self.NO_ENV_CMD):
            self._logger.info("`cli_syslog` found in the base environment")
            return self.NO_ENV_CMD

        if not self._pyenv_available():
            self._raise_cli_not_found_error(self.NO_ENV_CMD)

        venv_names = self._get_pyenv_venv_names_with_cli_syslog()
        if not venv_names:
            self._raise_cli_not_found_error(self.NO_ENV_CMD)
        venv_name = venv_names[-1]  # the last one is expected to be a venv name without path prefix
        self._logger.info(
            f"`cli_syslog` command exists in Python versions: {', '.join(venv_names)}"
            f"\nWe will use: {venv_name}"
        )
        return self.PYENV_CMD.format(venv_name)

    def _syslog_available_in_environment(self, env_cmd: str) -> bool:
        # In CM VM:
        # command -v cli_syslog -> /home/ute/.pyenv/shims/cli_syslog
        # which doesn't help much, hence False
        check_cmd = env_cmd + "command -v cli_syslog"
        process = self._send_ssh_command(check_cmd)
        output = process.read_output().strip()
        if ".pyenv/shims/cli_syslog" in output:
            return False
        ec = process.get_exit_code()
        return ec == 0

    def _pyenv_available(self) -> bool:
        process = self._send_ssh_command("test -f $HOME/.pyenv/bin/pyenv")
        ec = process.get_exit_code()
        return ec == 0

    def _raise_cli_not_found_error(self, env_cmd: str) -> NoReturn:
        path = self._get_path_from_environment(env_cmd)
        paths = "\n".join(path.split(":"))
        msg_header = "`cli_syslog` was not found in PATH. Please make sure it is installed in correct environment. "
        msg_path = f"At the time of execution we found these paths in PATH:\n{paths}"
        msg = msg_header + msg_path
        raise SyslogCLINotFoundError(textwrap.dedent(msg))

    def _get_path_from_environment(self, env_cmd: str) -> str:
        get_path_cmd = env_cmd + "echo $PATH"
        process = self._send_ssh_command(get_path_cmd)
        return process.read_output()

    def _get_pyenv_venv_names_with_cli_syslog(self) -> list[str]:
        # will return e.g., ["3.11.9/envs/test_repo", "test_repo"]
        process = self._send_ssh_command("pyenv whence cli_syslog")
        venvs = process.read_output().strip().splitlines()
        return venvs
